def _format_t(path, root=T):
    """Format a T-like object's operations into a string representation."""
    if not path:
        # Just the root
        if root is T:
            return 'T'
        elif root is S:
            return 'S'
        elif root is A:
            return 'A'
        return repr(root)

    # Build the representation
    root_name = {T: 'T', S: 'S', A: 'A'}.get(root, repr(root))
    result = root_name

    i = 0
    while i < len(path):
        op = path[i]
        arg = path[i + 1] if i + 1 < len(path) else None

        if op == '.':
            result += f'.{arg}'
        elif op == '[':
            result += f'[{bbrepr(arg)}]'
        elif op == 'P':
            result += f'[{bbrepr(arg)}]'
        elif op == '(':
            args, kwargs = arg
            args_str = ', '.join(bbrepr(a) for a in args)
            kwargs_str = ', '.join(f'{k}={bbrepr(v)}' for k, v in kwargs.items())
            all_args = ', '.join(filter(None, [args_str, kwargs_str]))
            result += f'({all_args})'
        elif op == 'x':
            result += '.__star__()'
        elif op == 'X':
            result += '.__starstar__()'
        elif op in ('+', '-', '*', '/', '%', ':', '&', '|', '^'):
            result = f'({result} {op} {bbrepr(arg)})'
        elif op == '#':
            result = f'({result} // {bbrepr(arg)})'
        elif op == '~':
            result = f'(~{result})'
        elif op == '_':
            result = f'(-{result})'

        i += 2

    return result
